import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None

materials_data = request("GET", "/materials")
materials = materials_data if isinstance(materials_data, list) else materials_data.get("materials", [])

classified = []
for material in materials:
    result = request("POST", "/materials/classify", json={"material": material})
    classified.append({"material": material, "classification": result})

compliance_results = []
for item in classified:
    classification = item["classification"] or {}
    material = item["material"] or {}
    requires_compliance = classification.get("requires_compliance_check") or classification.get("compliance_required")
    material_id = material.get("id") or classification.get("material_id")

    if requires_compliance and material_id:
        compliance = request("GET", f"/materials/{material_id}/compliance")
        calculation_id = compliance.get("calculation_id") if isinstance(compliance, dict) else None
        calculation_result = (
            request("GET", f"/calculations/{calculation_id}/result")
            if calculation_id
            else None
        )
        compliance_results.append({
            "material_id": material_id,
            "compliance": compliance,
            "calculation_result": calculation_result,
        })

inventory_status = request("GET", "/inventory/status")

route_payload = {
    "materials": [
        {
            "material_id": item["material"].get("id"),
            "classification": item["classification"],
            "compliance": next(
                (result for result in compliance_results
                 if result["material_id"] == item["material"].get("id")),
                None,
            ),
        }
        for item in classified
    ],
    "inventory_status": inventory_status,
}
route_update = request("PATCH", "/logistics/route", json=route_payload)

equipment_id = os.getenv("EQUIPMENT_ID", "123")
maintenance_schedule = os.getenv("MAINTENANCE_SCHEDULE", "2026-11-01T08:00:00Z")
maintenance_update = request(
    "POST",
    "/equipment/maintenance-schedule",
    json={"equipmentId": equipment_id, "schedule": maintenance_schedule},
)

resource_usage_statistics = request("GET", "/analysis/statistics", params={"metric": "resource_usage"})

